          "“Một lần là ngẫu nhiên. Hai lần thì là luật.”",
          "Một nơi vừa lạ vừa quá yên. Ở giữa cảnh ấy, luật mới này nhỏ hơn mọi thứ xung quanh, và cũng nguy hiểm hơn.",
