          "Chàng trai bước sang một bên, che phần vừa xuất hiện. Nhật Ký Sinh Tồn Tấu Hài Của Nữ Chính Trên Hoang Đảo — nếu câu này lọt ra ngoài, đêm nay không còn yên.",
          "Chàng trai nói, giọng đều: “Nhầm chỗ. Tôi không bán gì cả.”",
